scenarios.example_code:
import { createContact } from '@projexlight/sdk-crm';
const { contact_id, duplicate_of } = await createContact({
  tenant_id, email: 'alice@acme.com', full_name: 'Alice Smith',
  source: 'webform:eu-q2-campaign',
});

import { convertLead } from '@projexlight/sdk-crm';
const { contact_id, deal_id } = await convertLead({
  lead_id, deal_amount_cents: 120_000_00, deal_owner_persona_id: ae.id,
});

import { advanceDeal } from '@projexlight/sdk-crm';
await advanceDeal({
  deal_id, to_stage: 'proposal', reason: 'demo accepted', persona_id: ae.id,
});

subscribeEvents('connector-salesforce.webhook.received.v1', async (e) => {
  if (e.payload.event_type !== 'ContactCreated') return;
  await upsertContactFromExternal({ external_id: e.payload.sf_id, ...e.payload.fields });
});

import { exportToConnector } from '@projexlight/sdk-crm';
await exportToConnector({
  entity_kind: 'deal', entity_id: deal_id,
  connector: '@projexlight/connector-salesforce',
});
